'use strict';

const express = require('express');
const { sendError } = require('../utils/errors');

const PLAYERS_COLLECTION = 'players';
const SAVES_COLLECTION = 'saves';

/**
 * Creates the Saves Express router.
 * 
 * @param {object} options
 * @param {object} options.storage - Conforming storage adapter
 * @returns {import('express').Router}
 */
function createSavesRouter({ storage }) {
  const router = express.Router();
  router.use(express.json());

  /**
   * PUT /:playerId
   * Stores any JSON save data for a player.
   * Body: { data: any } or any valid JSON object
   */
  router.put('/:playerId', async (req, res, next) => {
    try {
      const { playerId } = req.params;

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'Invalid playerId');
      }

      const cleanPlayerId = playerId.trim();

      // Check player exists
      const player = await storage.get(PLAYERS_COLLECTION, cleanPlayerId);
      if (!player) {
        return sendError(res, 404, 'Player not found');
      }

      const body = req.body;
      if (!body || typeof body !== 'object' || Array.isArray(body)) {
        return sendError(res, 400, 'Save data must be a valid JSON object');
      }

      // If wrapped in { data: ... }, extract or store body
      const saveData = Object.prototype.hasOwnProperty.call(body, 'data') ? body.data : body;

      const record = {
        playerId: cleanPlayerId,
        data: saveData,
        updatedAt: new Date().toISOString()
      };

      await storage.set(SAVES_COLLECTION, cleanPlayerId, record);

      return res.status(200).json(record);
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /:playerId
   * Fetches save data for a player.
   */
  router.get('/:playerId', async (req, res, next) => {
    try {
      const { playerId } = req.params;

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'Invalid playerId');
      }

      const cleanPlayerId = playerId.trim();
      const saveRecord = await storage.get(SAVES_COLLECTION, cleanPlayerId);

      if (!saveRecord) {
        return sendError(res, 404, 'Save data not found');
      }

      return res.status(200).json(saveRecord);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = {
  createSavesRouter
};
